
-- ============================================================
-- BLOCK 2 — WRITES (run only after reviewing BLOCK 1's output)
-- ============================================================

-- 2a-2c run as a single transaction, inside one PL/pgSQL DO block guarded
-- by an "already applied?" check (see header note): either all of it
-- lands (deactivation + both inserts) or none of it does, and a second run
-- is a true no-op. 2d (below, outside the transaction) is a read-only
-- check of whatever state actually committed.
begin;

do $ufc_seed$
declare
  v_already_applied boolean;
  v_max_quiz_id bigint;
  v_max_guess_id bigint;
begin
  select exists (
    select 1 from public.quiz_questions where level <> 'მარტივი' and is_active = true
    union all
    select 1 from public.guess_who_questions where level <> 'მარტივი' and is_active = true
  ) into v_already_applied;

  if v_already_applied then
    raise notice 'ufc_quiz_seed: content already active -- 2a/2b/2c skipped (no-op).';
    return;
  end if;

-- 2a. Deactivate the legacy rows (do NOT delete, do NOT edit their text).
-- `id <= max(id)`, captured dynamically right here instead of a
-- guessed/hardcoded range — see header note for why this is safe.
select max(id) into v_max_quiz_id from public.quiz_questions;
select max(id) into v_max_guess_id from public.guess_who_questions;

update public.quiz_questions
set is_active = false
where id <= v_max_quiz_id;

update public.guess_who_questions
set is_active = false
where id <= v_max_guess_id;

-- 2b. Insert the 294 Part B quiz questions (idempotent: skips any row
-- whose exact question text + level already exists).
insert into public.quiz_questions (question, options, correct_index, level, category, is_active)
select v.question, v.options, v.correct_index, v.level, 'UFC', true
from (
  values
  ($gq$რას ნიშნავს აბრევიატურა "UFC"?$gq$, to_jsonb(ARRAY[$gq$United Fighting Federation$gq$, $gq$Ultimate Fighting Championship$gq$, $gq$Universal Fighting Club$gq$, $gq$Underground Fighting Circuit$gq$]::text[]), 1, $gq$მარტივი$gq$),
  ($gq$რა გეომეტრიული ფორმისაა UFC-ის სტანდარტული საბრძოლო გალია?$gq$, to_jsonb(ARRAY[$gq$კვადრატი$gq$, $gq$წრე$gq$, $gq$რვაკუთხედი (ოქტაგონი)$gq$, $gq$ექვსკუთხედი$gq$]::text[]), 2, $gq$მარტივი$gq$),
  ($gq$ვინ არის UFC-ის მრავალწლიანი აღმასრულებელი დირექტორი და მთავარი საჯარო სახე?$gq$, to_jsonb(ARRAY[$gq$სკოტ კოკერი$gq$, $gq$ჩატრი სიტიოდტონგი$gq$, $gq$დანა უაითი$gq$, $gq$არიელ ჰელვანი$gq$]::text[]), 2, $gq$მარტივი$gq$),
  ($gq$რომელი ირლანდიელი მებრძოლი გახდა ისტორიაში პირველი, ვინც ერთდროულად ფლობდა უდავო ტიტულს UFC-ის ორ წონით კატეგორიაში?$gq$, to_jsonb(ARRAY[$gq$კონორ მაკგრეგორი$gq$, $gq$იან მაჩადო გარი$gq$, $gq$კათალ პენდრედი$gq$, $gq$არტემ ლობოვი$gq$]::text[]), 0, $gq$მარტივი$gq$),
