-- 2c. Insert the 60 Part A fighters (idempotent: skips any row whose exact
-- answer + level already exists). clue4 is '' (empty string) for the 5
-- three-clue fighters (#34, #36, #41, #47, #53) — clue4 is NOT NULL on
-- this table, and quiz_pvp.sql/quiz_group_pvp.sql/quiz.js's
-- normalizeGuessRow all filter clues with "not null and length(trim(...))
-- > 0" (or the JS equivalent), so '' is dropped exactly like NULL would
-- have been and the 4th clue never renders. Not padded with real content.
insert into public.guess_who_questions (answer, level, clue1, clue2, clue3, clue4, is_active)
select v.answer, v.level, v.clue1, v.clue2, v.clue3, v.clue4, true
from (
  values
  ($gq$ჯონ ჯონსი$gq$, $gq$მარტივი$gq$, $gq$ჩემს პროფესიონალურ კარიერაში მაქვს მხოლოდ 1 ოფიციალური წაგება, რომელიც დისკვალიფიკაციით მივიღე აკრძალული დარტყმების (12-6 იდაყვები) გამო, ბრძოლაში, რომელსაც აშკარად ვიგებდი.$gq$, $gq$მე ვფლობ UFC-ის ისტორიაში ყველაზე გრძელი ტიტულის მფლობელობის სერიას ქვემძიმე წონაში (Light Heavyweight) და ყველაზე მეტი — 16 — გამარჯვება მაქვს სატიტულო ბრძოლებში (აქედან 14 ამ დივიზიონში).$gq$, $gq$მე გავხდი UFC-ის ისტორიაში ყველაზე ახალგაზრდა ჩემპიონი, როდესაც ქამარი 23 წლის ასაკში მოვიგე.$gq$, $gq$ჩემი მეტსახელია "Bones", ვარ ქვემძიმე წონის (Light Heavyweight) ყოფილი და მძიმე წონის (Heavyweight) ჩემპიონი, ბევრი მთვლის ყველა დროის საუკეთესოდ (GOAT).$gq$),
  ($gq$ხაბიბ ნურმაგომედოვი$gq$, $gq$მარტივი$gq$, $gq$UFC-ში ჩემი ერთ-ერთი ყველაზე მძიმე ბრძოლა იყო აბელ ტრუხილიოს წინააღმდეგ, სადაც დავამყარე რეკორდი ერთ ბრძოლაში ყველაზე მეტი (21) თეიქდაუნით.$gq$, $gq$კარიერაში ჩატარებული 29 ბრძოლიდან, მსაჯების ქულების მიხედვით, ოფიციალურად მხოლოდ 2 რაუნდი მაქვს წაგებული (ერთი კონორ მაკგრეგორთან, მეორე ჯასტინ გეიჯისთან).$gq$, $gq$ჩემი ყველაზე ხმაურიანი ბრძოლა იყო UFC 229-ზე, რის შემდეგაც ოქტაგონიდან გადმოვხტი და მოწინააღმდეგის გუნდს თავს დავესხი.$gq$, $gq$ვარ დაღესტნელი „არწივი“ (The Eagle), დავტოვე სპორტი დაუმარცხებელმა, 29-0 რეკორდით და მსუბუქი წონის (Lightweight) ჩემპიონის სტატუსით.$gq$),
  ($gq$ანდერსონ სილვა$gq$, $gq$მარტივი$gq$, $gq$მიუხედავად იმისა, რომ ჩემი დივიზიონის ლეგენდა ვარ, UFC-ში ქვემძიმე წონაშიც (Light Heavyweight) ვიბრძოდი და იქ სამი გამარჯვება ნოკაუტით მოვიპოვე (მათ შორის ფორესტ გრიფინთან).$gq$, $gq$2006-დან 2012 წლამდე დავაგროვე 16-მატჩიანი მოგებათა სერია, რომელიც წლების განმავლობაში UFC-ის ისტორიაში ყველაზე გრძელი იყო.$gq$, $gq$ჩემი დომინაცია საშუალო წონაში (Middleweight) დასრულდა მას შემდეგ, რაც ქამარი მოულოდნელად წავაგე კრის ვაიდმანთან, ხოლო განმეორებით ბრძოლაში ფეხი მოვიტეხე.$gq$, $gq$ჩემი მეტსახელია "The Spider" (ობობა), ვარ ბრაზილიელი მებრძოლი, ცნობილი ჩემი წარმოუდგენელი, „მატრიცისებური“ რეფლექსებით.$gq$),
  ($gq$დემეტრიუს ჯონსონი$gq$, $gq$საშუალო$gq$, $gq$გავაკეთე უნიკალური საბმიშენი — მოწინააღმდეგე (რეი ბორგი) ჰაერში ავაგდე და დაცემამდე „არმბარი“ დავუჭირე.$gq$, $gq$მე ვარ UFC-ის ისტორიაში პირველი, ინაუგურაციული ჩემპიონი ჩემს წონაში, რომელიც ტურნირის მოგების შემდეგ გავხდი.$gq$, $gq$ვფლობ რეკორდს ზედიზედ ყველაზე მეტი — 11 ტიტულის წარმატებული დაცვით.$gq$, $gq$ჩემი მეტსახელია "Mighty Mouse", ვარ უმსუბუქესი წონის (Flyweight) ლეგენდა, რომელიც მოგვიანებით ONE Championship-ში გადავიდა.$gq$),
  ($gq$კამარუ უსმანი$gq$, $gq$საშუალო$gq$, $gq$ძირითად ქარდებამდე გავხდი რეალითი შოუს The Ultimate Fighter 21-ის გამარჯვებული.$gq$, $gq$დავაგროვე 15-მატჩიანი მოგებათა სერია — რეკორდი ქვესაშუალო წონის (Welterweight) დივიზიონის ისტორიაში.$gq$, $gq$ჩემი დომინაცია დასრულდა მე-5 რაუნდში, როცა ლეონ ედვარდსმა ჰედ-ქიქით ნოკაუტში ჩამაგდო.$gq$, $gq$ჩემი მეტსახელია "The Nigerian Nightmare", ვარ ქვესაშუალო წონის (Welterweight) ყოფილი დომინანტი ჩემპიონი.$gq$),
  ($gq$ამანდა ნუნესი$gq$, $gq$მარტივი$gq$, $gq$UFC-ში გადმოსვლამდე ვჩხუბობდი Strikeforce-სა და Invicta FC-ში, სადაც ალექსის დევისთან ტექნიკური ნოკაუტით წავაგე.$gq$, $gq$მე გავხდი პირველი ქალი UFC-ის ისტორიაში, რომელმაც ორ სხვადასხვა წონაში ჩემპიონობა ერთდროულად მოიპოვა და ორივე ქამარი აქტიურად დაიცვა.$gq$, $gq$ჩემი ყველაზე სწრაფი ტიტულის დაცვა მოხდა რონდა როუზის წინააღმდეგ, რომელიც 48 წამში დავამარცხე ნოკაუტით.$gq$, $gq$მე მქვია "The Lioness", ვარ ბრაზილიელი და აღიარებული ყველა დროის საუკეთესო ქალ მებრძოლად (GOAT).$gq$),
  ($gq$ისრაელ ადესანია$gq$, $gq$მარტივი$gq$, $gq$MMA-მდე მქონდა დიდი კარიერა კიკბოქსინგში (Glory), სადაც ჩემი რეკორდი 75 მოგება და 5 წაგებაა.$gq$, $gq$ჩემი ყველაზე დიდი მეტოქე ალექს პერეირაა, რომელთანაც კიკბოქსინგსა და MMA-ში ჯამში 4-ჯერ ვიჩხუბე და მხოლოდ 1 ბრძოლა მოვიგე (UFC 287-ზე ნოკაუტით).$gq$, $gq$ჩემი პირველი ოფიციალური მარცხი MMA-ში მოხდა მაშინ, როცა წონა ავიარე და ქვემძიმე წონის (Light Heavyweight) ჩემპიონთან, იან ბლაჰოვიჩთან წავაგე ქულებით.$gq$, $gq$ჩემი მეტსახელია "The Last Stylebender", ვარ ნიგერიული წარმოშობის ახალზელანდიელი საშუალო წონის (Middleweight) ორგზის ჩემპიონი.$gq$),
  ($gq$შონ ომალი$gq$, $gq$მარტივი$gq$, $gq$UFC-ის კონტრაქტი მოვიპოვე Dana White's Contender Series-ში ეპიკური ნოკაუტის შემდეგ, რასაც სნუპ დოგის ემოციური რეაქცია მოჰყვა.$gq$, $gq$ჩემი პირველი ოფიციალური წაგება იყო მარლონ „ჩიტო“ ვერასთან, როცა ბრძოლის დროს ნერვის დაზიანების გამო ფეხი გამეთიშა.$gq$, $gq$ჩემპიონი გავხდი მას შემდეგ, რაც მეორე რაუნდში მარჯვენა კონტრ-დარტყმით ნოკაუტში ჩავაგდე ალჯამეინ სტერლინგი.$gq$, $gq$მე მქვია "Suga", ცნობილი ვარ ფერადი თმებით და მოვიგე სუპერმსუბუქი წონის (Bantamweight) ქამარი, რომელიც მერაბ დვალიშვილთან წავაგე.$gq$),
  ($gq$მერაბ დვალიშვილი$gq$, $gq$მარტივი$gq$, $gq$UFC-ში ჩემი დებიუტი მძიმე გამოდგა — პირველი ორი ბრძოლა წავაგე (ფრენკი საენზთან და რიკი საიმონთან საკამათო საბმიშენით).$gq$, $gq$პეტრ იანთან ბრძოლაში დავამყარე რეკორდი ერთ ბრძოლაში შესრულებული თეიქდაუნების მცდელობებით (სულ 49 მცდელობა).$gq$, $gq$უარი ვთქვი ჩემს უახლოეს მეგობართან, ალჯამეინ სტერლინგთან ჩხუბზე, რის გამოც დანა უაიტი ხშირად მაკრიტიკებდა.$gq$, $gq$ჩემი მეტსახელია "The Machine", ვარ ქართველი მებრძოლი, ცნობილი გაუჩერებელი კარდიოთი, და სუპერმსუბუქი წონის (Bantamweight) ქამარი მოვიგე შონ ომალის დამარცხებით.$gq$),
  ($gq$ილია თოფურია$gq$, $gq$მარტივი$gq$, $gq$ჩემს სადებიუტო ბრძოლაში UFC-ში, რომელიც მოკლე დროში შეტყობინებით მივიღე, მსაჯების ერთსულოვანი გადაწყვეტილებით დავამარცხე იუსუფ ზალალი.$gq$, $gq$მე ვარ პირველი მებრძოლი UFC-ის ისტორიაში, რომელმაც ლეგენდარული მაქს ჰოლოუეი სუფთა ნოკაუტით დაამარცხა.$gq$, $gq$ჩემპიონი გავხდი მას შემდეგ, რაც მეორე რაუნდში მძიმე ჰუკით ნოკაუტში ჩავაგდე ალექსანდრ ვოლკანოვსკი.$gq$, $gq$ჩემი მეტსახელია "El Matador", ვარ პირველი ქართველი და ესპანელი, რომელმაც UFC-ის ქამარი მოიგო ქვემსუბუქ წონაში (Featherweight).$gq$),
  ($gq$ალექსანდრ ვოლკანოვსკი$gq$, $gq$მარტივი$gq$, $gq$MMA-მდე პროფესიონალურ დონეზე ვთამაშობდი რაგბის და ვიწონიდი დაახლოებით 97 კილოგრამს.$gq$, $gq$ორჯერ ავედი მსუბუქ წონაში (Lightweight), რათა გამომეწვია ისლამ მაჰაჩევი ორმაგი ჩემპიონობისთვის, თუმცა ორივეჯერ დავმარცხდი.$gq$, $gq$ვფლობდი ქვემსუბუქი წონის (Featherweight) ქამარს და ზედიზედ სამჯერ დავამარცხე მაქს ჰოლოუეი ჩვენს ტრილოგიაში.$gq$, $gq$ჩემი მეტსახელია "The Great", ვარ ავსტრალიელი ლეგენდა და ჩემი პირველი, ოთხწლიანი ჩემპიონობა ილია თოფურიამ დაასრულა.$gq$),
  ($gq$მაქს ჰოლოუეი$gq$, $gq$მარტივი$gq$, $gq$UFC-ში დებიუტი 20 წლის ასაკში შედგა და პირველივე ბრძოლა დასტინ პორიესთან საბმიშენით წავაგე.$gq$, $gq$კალვინ კატართან ბრძოლის დროს, პირდაპირ ოქტაგონიდან ვუყვიროდი კომენტატორებს: „მე ვარ საუკეთესო მოკრივე UFC-ში!“.$gq$, $gq$UFC 300-ზე ავედი მსუბუქ წონაში (Lightweight), ჯასტინ გეიჯი ბოლო წამზე ეპიკური ნოკაუტით დავამარცხე და მოვიგე BMF ქამარი.$gq$, $gq$ჩემი მეტსახელია "Blessed", ვარ ჰავაიელი ქვემსუბუქი წონის (Featherweight) ყოფილი ჩემპიონი, ცნობილი წარმოუდგენელი ნიკაპით.$gq$),
  ($gq$კონორ მაკგრეგორი$gq$, $gq$მარტივი$gq$, $gq$სანამ ლეგენდარულ სერიას დავიწყებდი, UFC-ში მეორე ბრძოლა მაქს ჰოლოუეისთან ერთსულოვანი გადაწყვეტილებით მოვიგე, მიუხედავად იმისა, რომ ჩხუბის დროს მუხლის მყესი გავიწყვიტე.$gq$, $gq$მაქვს ნოკაუტით მოპოვებული გამარჯვებები სამ სხვადასხვა წონით კატეგორიაში — ქვემსუბუქ (Featherweight), მსუბუქ (Lightweight) და ქვესაშუალო (Welterweight) დივიზიონებში.$gq$, $gq$გავხდი პირველი მებრძოლი ორგანიზაციის ისტორიაში, ვინც ერთდროულად ორ სხვადასხვა წონის ქამარს ფლობდა.$gq$, $gq$ჩემი მეტსახელია "The Notorious", ვარ ირლანდიელი, დავამარცხე ხოსე ალდო 13 წამში და ვარ სპორტის ისტორიაში ყველაზე მაღალანაზღაურებადი ვარსკვლავი.$gq$),
  ($gq$დასტინ პორიე$gq$, $gq$საშუალო$gq$, $gq$ჩემზე გადაღებულია დოკუმენტური ფილმი "Fightville", რომელიც ასახავს კარიერას UFC-მდე, ლუიზიანას პატარა კლუბებში.$gq$, $gq$სამჯერ ვიბრძოლე მსუბუქი წონის (Lightweight) ჩემპიონობისთვის (ხაბიბთან, ოლივეირასთან, მაჰაჩევთან), თუმცა სამივეჯერ საბმიშენით წავაგე.$gq$, $gq$ვარ ის მებრძოლი, რომელმაც კონორ მაკგრეგორს კარიერაში პირველი ნოკაუტი აგემა, ხოლო მესამე ბრძოლაში ირლანდიელმა ფეხი მოიტეხა.$gq$, $gq$ჩემი მეტსახელია "The Diamond", ვარ ლუიზიანელი ყოფილი დროებითი ჩემპიონი, ცნობილი ქველმოქმედებითა და ეპიკური ომებით.$gq$),
  ($gq$ჩარლზ ოლივეირა$gq$, $gq$საშუალო$gq$, $gq$კარიერის დასაწყისში არასტაბილური ვიყავი, წონას ხშირად ვაგდებდი არასწორად და 4-ჯერ მაქვს წაგებული საბმიშენით.$gq$, $gq$მოვიგე მსუბუქი წონის (Lightweight) ვაკანტური ქამარი, როცა მძიმე ნოკდაუნიდან წამომდგარმა მეორე რაუნდში ტექნიკური ნოკაუტით დავამარცხე მაიკლ ჩენდლერი.$gq$, $gq$ვფლობ რეკორდს UFC-ის ისტორიაში ყველაზე მეტი საბმიშენით მოგებითა და ფინიშით.$gq$, $gq$ჩემი მეტსახელია "Do Bronx", ვარ ბრაზილიელი, გამოვირჩევი უმაღლესი დონის ჯიუ-ჯიცუთი და ვარ მსუბუქი წონის (Lightweight) ყოფილი ჩემპიონი.$gq$),
  ($gq$ისლამ მაჰაჩევი$gq$, $gq$მარტივი$gq$, $gq$ჩემს კარიერაში მაქვს მხოლოდ 1 მარცხი, რომელიც 2015 წელს UFC-ში ჩემს მეორე ბრძოლაში ადრიანო მარტინსთან ნოკაუტით მივიღე.$gq$, $gq$ჩემპიონი გავხდი მას შემდეგ, რაც დომინანტურ სტილში, „არმ-ტრაიანგლ“ საბმიშენით დავამარცხე ჩარლზ ოლივეირა.$gq$, $gq$ჩემი მთავარი მწვრთნელი და მენტორი არის ლეგენდარული ხაბიბ ნურმაგომედოვი.$gq$, $gq$ვარ დაღესტნელი მებრძოლი, რომელმაც მსუბუქი წონის (Lightweight) ქამარი მოიგო და P4P რეიტინგს ლიდერობდა.$gq$),
  ($gq$ალექს პერეირა$gq$, $gq$მარტივი$gq$, $gq$გავხდი პირველი მებრძოლი Glory კიკბოქსინგის ისტორიაში, რომელიც ერთდროულად ორ წონაში ფლობდა ჩემპიონის ქამარს.$gq$, $gq$დავამყარე რეკორდი, როგორც ყველაზე სწრაფად (7 ბრძოლაში) ორგზის ჩემპიონმა UFC-ის ისტორიაში.$gq$, $gq$ჩემი საფირმო იარაღია მარცხენა ჰუკი, რომლითაც ნოკაუტში ჩავაგდე ჯამაჰალ ჰილი; ნოკაუტით დავამარცხე ირჟი პროჰასკა და ისრაელ ადესანიაც.$gq$, $gq$ჩემი მეტსახელია "Poatan" (ქვის ხელი), ვარ ბრაზილიელი საშუალო და ქვემძიმე წონის (Light Heavyweight) ჩემპიონი, ოქტაგონზე გამოსვლისას მშვილდ-ისრის იმიტაციას ვაკეთებ.$gq$),
  ($gq$სტიპე მიოჩიჩი$gq$, $gq$საშუალო$gq$, $gq$ჩემპიონობამდე ერთ-ერთი მძიმე წაგება იყო სტეფან სტრუვესთან, რომელმაც გრძელი ხელების წყალობით ტექნიკური ნოკაუტით მომიგო.$gq$, $gq$მაქვს ლეგენდარული ტრილოგია დანიელ კორმიესთან, სადაც პირველი ბრძოლა ნოკაუტით წავაგე, თუმცა მომდევნო ორივე მოვიგე.$gq$, $gq$ვფლობ რეკორდს მძიმე წონაში (Heavyweight) ტიტულის ზედიზედ ყველაზე მეტი (3) წარმატებული დაცვით.$gq$, $gq$ვარ ოჰაიოელი ხორვატული წარმოშობის მებრძოლი, რომელიც სრულ განაკვეთზე მეხანძრე-პარამედიკოსად მუშაობს.$gq$),
  ($gq$ჟანგ ვეილი$gq$, $gq$საშუალო$gq$, $gq$MMA-მდე ვმუშაობდი საბავშვო ბაღის მასწავლებლად, სასტუმროს ადმინისტრატორად და ფიტნეს ინსტრუქტორად.$gq$, $gq$იოანა ენდჟეიჩიკთან ჩემი პირველი ბრძოლა (UFC 248) აღიარებულია ქალთა MMA-ის ისტორიაში საუკეთესო ჩხუბად.$gq$, $gq$მე ვარ პირველი ჩინელი ჩემპიონი UFC-ის ისტორიაში და მოვიგე მინიმალური წონის (Strawweight) ქამარი.$gq$, $gq$ჩემი მეტსახელია "Magnum", ვარ ჩინეთის უდიდესი MMA ვარსკვლავი, ცნობილი ფიზიკური ძალითა და აგრესიული სტრაიკინგით.$gq$),
  ($gq$ფრენსის ნგანუ$gq$, $gq$მარტივი$gq$, $gq$კამერუნიდან ევროპაში არალეგალური მიგრაციის დროს, ესპანეთში საზღვრის უკანონო გადაკვეთისთვის 2 თვე ციხეში გავატარე.$gq$, $gq$ჩემს პირველ სატიტულო ბრძოლაში სტიპე მიოჩიჩმა გამოუცდელობა გამომიყენა და 5 რაუნდის განმავლობაში ჭიდაობით დამღალა და მომიგო.$gq$, $gq$რევანშში სტიპე სასტიკად დავამარცხე ნოკაუტით, მოვიგე მძიმე წონის (Heavyweight) ქამარი, თუმცა მოგვიანებით ორგანიზაცია დავტოვე და კრივში გადავედი ტაისონ ფიურისთან.$gq$, $gq$ჩემი მეტსახელია "The Predator", ვარ კამერუნელი, ითვლება სპორტის ისტორიაში ყველაზე საშიში დარტყმის მქონე ნოკაუტერად.$gq$),
  ($gq$რონდა როუზი$gq$, $gq$მარტივი$gq$, $gq$MMA-მდე ვიყავი ძიუდოისტი და მოვიპოვე ბრინჯაოს მედალი 2008 წლის პეკინის ოლიმპიადაზე.$gq$, $gq$კარიერის დასაწყისში ზედიზედ 7 გამარჯვება მოვიპოვე ერთი და იმავე ილეთით — პირველსავე რაუნდში გაკეთებული „არმბარით“.$gq$, $gq$ჩემი დომინაცია შოკისმომგვრელად დასრულდა, როცა ჰოლი ჰოლმმა ჰედ-ქიქით ნოკაუტში ჩამაგდო.$gq$, $gq$მე ვარ UFC-ის ისტორიაში პირველი ქალი ჩემპიონი სუპერმსუბუქ წონაში (Bantamweight) და პირველი ქალი დიდების დარბაზში.$gq$),
  ($gq$ნეიტ დიასი$gq$, $gq$მარტივი$gq$, $gq$გავხდი რეალითი შოუს The Ultimate Fighter 5-ის გამარჯვებული, სადაც ფინალში მანველ გამბურიანი დავამარცხე.$gq$, $gq$ცნობილი ვარ საფირმო ჟესტით — ბრძოლის დროს მოწინააღმდეგისთვის სახეში ღია ხელის ჩარტყმით ("Stockton Slap").$gq$, $gq$ვიყავი პირველი მებრძოლი, რომელმაც კონორ მაკგრეგორი UFC-ში დაამარცხა, როცა ბრძოლა მოკლე დროში მივიღე და მეორე რაუნდში მოგუდვით დავაფინიშე.$gq$, $gq$ვარ სტოკტონელი მებრძოლი, ნიკ დიასის უმცროსი ძმა, ცნობილი გაუტეხელი ხასიათითა და დიდი კარდიოთი.$gq$),
  ($gq$ხორხე მასვიდალი$gq$, $gq$მარტივი$gq$, $gq$კარიერის დასაწყისში პოპულარობა მოვიპოვე ვიდეოებით, სადაც მაიამის უკანა ეზოებში ქუჩის ჩხუბებში ვმონაწილეობდი.$gq$, $gq$ნეიტ დიასთან გამარჯვების შემდეგ, გავხდი UFC-ის ისტორიაში პირველი ოფიციალური "BMF" ქამრის მფლობელი.$gq$, $gq$დავამყარე რეკორდი UFC-ის ისტორიაში ყველაზე სწრაფი ნოკაუტით, როცა ბენ ასკრენი მფრინავი მუხლით 5 წამში გავთიშე.$gq$, $gq$ჩემი მეტსახელია "Gamebred", ვარ მაიამელი ვეტერანი, ცნობილი ფრაზით "Three Piece and a Soda".$gq$),
  ($gq$პეტრ იანი$gq$, $gq$საშუალო$gq$, $gq$UFC-მდე ვფლობდი რუსული ორგანიზაცია ACB-ის ქვემსუბუქი წონის (Featherweight) ქამარს.$gq$, $gq$პირველი ჩემპიონობა დავკარგე შეცდომის გამო — ალჯამეინ სტერლინგთან ბრძოლას ვიგებდი, მაგრამ მე-4 რაუნდში დაჩოქილ მეტოქეს აკრძალული მუხლი ჩავარტყი და დისკვალიფიკაციით წავაგე.$gq$, $gq$ვაკანტური ქამრისთვის ბრძოლაში ტექნიკური ნოკაუტით დავამარცხე ლეგენდა ჟოზე ალდო.$gq$, $gq$ჩემი მეტსახელია "No Mercy", ვარ ციმბირელი უმაღლესი დონის მოკრივე, რომელმაც სუპერმსუბუქი წონის (Bantamweight) ქამარი მოიგო.$gq$),
  ($gq$ირჟი პროჰასკა$gq$, $gq$საშუალო$gq$, $gq$კარიერის დიდ ნაწილში ვჩხუბობდი იაპონურ ორგანიზაცია Rizin-ში, სადაც მოვიგე ქვემძიმე წონის (Light Heavyweight) ქამარი.$gq$, $gq$ჩემპიონი გავხდი UFC-ში მხოლოდ მესამე ბრძოლაში, როცა გლოვერ ტეიშეირა მე-5 რაუნდის ბოლო წუთზე მოგუდვით დავამარცხე.$gq$, $gq$ნებაყოფლობით დავთმე ქამარი ბრძოლის გარეშე, რადგან მხრის უმძიმესი ტრავმა მივიღე.$gq$, $gq$ვარ ჩეხი მებრძოლი, რომელიც მისდევს სამურაების კოდექსს და ცნობილია უცნაური ვარცხნილობითა და შეძახილით "BJP!".$gq$),
  ($gq$ჯასტინ გეიჯი$gq$, $gq$საშუალო$gq$, $gq$UFC-მდე ვიყავი WSOF-ის დაუმარცხებელი ჩემპიონი და ჩემი პირველი 3 ბრძოლა UFC-ში ზედიზედ "Fight of the Night" ბონუსით დასრულდა.$gq$, $gq$გავაჩერე ტონი ფერგიუსონის 12-მატჩიანი სერია, როცა მე-5 რაუნდში ტექნიკური ნოკაუტით მოვიგე დროებითი ქამარი.$gq$, $gq$დასტინ პორიესთან მეორე ბრძოლაში ის ჰედ-ქიქით დავაფინიშე და მოვიგე BMF ქამარი, რომელიც მოგვიანებით მაქს ჰოლოუეისთან წავაგე.$gq$, $gq$ჩემი მეტსახელია "The Highlight", ვარ ყველაზე სანახაობრივი მებრძოლი, ცნობილი გამანადგურებელი ლოუ-ქიქებით.$gq$),
  ($gq$რობერტ ვიტეკერი$gq$, $gq$საშუალო$gq$, $gq$UFC-ში კარიერა დავიწყე ქვესაშუალო წონაში (Welterweight) და მოვიგე რეალითი შოუ The Ultimate Fighter: The Smashes.$gq$, $gq$საშუალო წონაში (Middleweight) გადმოსვლის შემდეგ გავხდი ჩემპიონი და ჩავატარე ორი ომი იოელ რომეროსთან, ორივეჯერ ქულებით გავიმარჯვე.$gq$, $gq$ჩემი ჩემპიონობის ერა დასრულდა, როცა ისრაელ ადესანიამ ნოკაუტით დამამარცხა ჩემსავე მშობლიურ ქვეყანაში.$gq$, $gq$ჩემი მეტსახელია "The Reaper", ვარ ავსტრალიელი საშუალო წონის (Middleweight) ყოფილი ჩემპიონი, ცნობილი როგორც სპორტის ერთ-ერთი ყველაზე პატივსაცემი ადამიანი.$gq$),
  ($gq$კოლბი კოვინგტონი$gq$, $gq$საშუალო$gq$, $gq$სადებიუტო წლებში ვიყავი მშვიდი მოჭიდავე, მაგრამ დემიან მაიასთან ბრძოლის შემდეგ ბრაზილიელ პუბლიკას „ცხოველები“ ვუწოდე და ასე დავიწყე „თრეშთოქერული“ იმიჯი.$gq$, $gq$სამჯერ ვიბრძოლე ქვესაშუალო წონის (Welterweight) ქამრისთვის (ორჯერ უსმანთან, ერთხელ ლეონ ედვარდსთან), თუმცა სამივე წავაგე.$gq$, $gq$ჩემი ყველაზე პრინციპული დაპირისპირება იყო ყოფილ საუკეთესო მეგობართან, ხორხე მასვიდალთან, რომელიც დავამარცხე.$gq$, $gq$ჩემი მეტსახელია "Chaos", ვარ ამერიკელი ქვესაშუალო წონის (Welterweight) მებრძოლი, ცნობილი ულტრა-პატრიოტული იმიჯითა და გაუჩერებელი საუბრით.$gq$),
  ($gq$ლეონ ედვარდსი$gq$, $gq$საშუალო$gq$, $gq$ბავშვობაში, იამაიკიდან ბრიტანეთში გადასვლის შემდეგ, ჩემი მამა ლონდონის ღამის კლუბში მოკლეს, რის შემდეგაც დედამ MMA-ზე შეყვანით გადამარჩინა.$gq$, $gq$უსმანთან პირველი ბრძოლა წავაგე, მაგრამ რევანშში, როცა ბრძოლას ვაგებდი, მე-5 რაუნდის დასასრულს ჰედ-ქიქით ნოკაუტში ჩავაგდე ის.$gq$, $gq$ხორხე მასვიდალთან კულისებს მიღმა ჩხუბის დროს სახეში დარტყმა მივიღე, რასაც მასვიდალმა "Three Piece and a Soda" უწოდა.$gq$, $gq$ჩემი მეტსახელია "Rocky", ვარ ბრიტანელი მებრძოლი და ქვესაშუალო წონის (Welterweight) ყოფილი ჩემპიონი.$gq$),
  ($gq$ბრენდონ მორენო$gq$, $gq$საშუალო$gq$, $gq$გამომაგდეს UFC-დან 2018 წელს ზედიზედ ორი წაგების შემდეგ, თუმცა სხვა ორგანიზაციაში (LFA) ქამარი მოვიგე და დამაბრუნეს.$gq$, $gq$მაქვს უნიკალური რეკორდი — პირველად ისტორიაში, მე და დეივესონ ფიგერედომ ზედიზედ 4-ჯერ ვიჩხუბეთ ჩემპიონობისთვის.$gq$, $gq$გავხდი პირველი მექსიკელი ჩემპიონი, როცა ფიგერედო ჩვენს მეორე ბრძოლაში (UFC 263) მესამე რაუნდში საბმიშენით დავამარცხე.$gq$, $gq$ჩემი მეტსახელია "The Assassin Baby", ვარ უმსუბუქესი წონის (Flyweight) ყოფილი ჩემპიონი, თავისუფალ დროს ვაწყობ ლეგოს.$gq$),
  ($gq$ტონი ფერგიუსონი$gq$, $gq$საშუალო$gq$, $gq$მოვიგე The Ultimate Fighter 13 ქვესაშუალო წონაში (Welterweight), თუმცა მოგვიანებით მსუბუქ წონაში (Lightweight) ჩამოვედი.$gq$, $gq$მე და ხაბიბ ნურმაგომედოვის ბრძოლა 5-ჯერ ჩაინიშნა და ხუთივეჯერ ჩაიშალა (მათ შორის ჩემი მხრიდან კაბელზე ფეხის წამოკვრისა და მუხლის გაწყვეტის გამო).$gq$, $gq$ვფლობდი 12-მატჩიან სერიას მსუბუქ წონაში (Lightweight), თუმცა ჯასტინ გეიჯისთან წაგების შემდეგ დამეწყო 8-მატჩიანი წაგებათა სერია.$gq$, $gq$ჩემი მეტსახელია "El Cucuy", ცნობილი ვარ გიჟური სავარჯიშოებითა და ფრაზით "Champ Shit Only".$gq$),
  ($gq$შონ სტრიკლენდი$gq$, $gq$საშუალო$gq$, $gq$კარიერის დასაწყისში ვჩხუბობდი ქვესაშუალო წონაში (Welterweight), სადაც კამარუ უსმანთანაც მაქვს წაგებული.$gq$, $gq$გადავიტანე უმძიმესი ავტოსაგზაო შემთხვევა მოტოციკლით, რის გამოც 2 წელი ჩამოვცილდი ოქტაგონს.$gq$, $gq$მოვახდინე უდიდესი სენსაცია, როცა 5 რაუნდში სტრაიკინგში ვაჯობე ისრაელ ადესანიას.$gq$, $gq$ვარ ამერიკელი, რომელმაც საშუალო წონის (Middleweight) ქამარი მოიგო; ცნობილი ვარ გიჟური ინტერვიუებითა და „Philly Shell“ დაცვით.$gq$),
  ($gq$დრიკუს დიუ პლესი$gq$, $gq$საშუალო$gq$, $gq$UFC-მდე ვიყავი პოლონური ორგანიზაცია KSW-ის ჩემპიონი.$gq$, $gq$ჩემპიონობის გზაზე ნოკაუტით დავამარცხე ყოფილი ჩემპიონი რობერტ ვიტეკერი.$gq$, $gq$ჩემპიონი გავხდი შონ სტრიკლენდის დამარცხების შემდეგ, პირველი დაცვა კი ისრაელ ადესანიასთან საბმიშენით მოვიპოვე.$gq$, $gq$ჩემი მეტსახელია "Stillknocks", ვარ ისტორიაში პირველი სამხრეთაფრიკელი UFC-ის ჩემპიონი.$gq$),
  ($gq$ჟოზე ალდო$gq$, $gq$საშუალო$gq$, $gq$WEC-ის UFC-სთან შერწყმის შემდეგ, ავტომატურად გადმომცეს UFC-ის ქვემსუბუქი წონის (Featherweight) პირველი ქამარი.$gq$, $gq$ვიყავი დაუმარცხებელი 10 წლის განმავლობაში, სანამ სერია კონორ მაკგრეგორმა 13 წამში არ დაასრულა.$gq$, $gq$ჩემი მეტსახელია "The King of Rio", ვარ ბრაზილიელი ქვემსუბუქი წონის (Featherweight) ისტორიაში საუკეთესო ჩემპიონი.$gq$, $gq$$gq$),
  ($gq$დანიელ კორმიე$gq$, $gq$საშუალო$gq$, $gq$მოვიგე Strikeforce-ის მძიმე წონის (Heavyweight) გრან-პრი, სადაც სათადარიგო მებრძოლად შევედი.$gq$, $gq$ჩემი ყველაზე დიდი დაპირისპირება იყო ჯონ ჯონსთან, ვისთანაც ორჯერ წავაგე (მეორე ბრძოლა გაუქმდა ჯონის დოპინგის გამო).$gq$, $gq$სტიპე მიოჩიჩთან პირველი ბრძოლის მოგების შემდეგ, გავხდი მძიმე და ქვემძიმე წონის (Light Heavyweight) ერთდროული ჩემპიონი.$gq$, $gq$ჩემი ინიციალებია "DC", ვარ ყოფილი ოლიმპიელი მოჭიდავე, რომელიც ამჟამად UFC-ის კომენტატორია.$gq$),
  ($gq$ალჯამეინ სტერლინგი$gq$, $gq$რთული$gq$, $gq$გავხდი პირველი მებრძოლი ისტორიაში, რომელმაც ქამარი მოწინააღმდეგის დისკვალიფიკაციის (პეტრ იანის აკრძალული მუხლის) გამო მიიღო.$gq$, $gq$რევანშში პეტრ იანი სუფთად, ჭიდაობის ხარჯზე დავამარცხე.$gq$, $gq$ჩემი მეტსახელია "Funk Master", ვარ იამაიკური წარმოშობის ამერიკელი, ვიყავი სუპერმსუბუქი წონის (Bantamweight) ჩემპიონი შონ ომალისთან წაგებამდე.$gq$, $gq$$gq$),
  ($gq$ტი ჯეი დილაშოუ$gq$, $gq$რთული$gq$, $gq$ვიყავი The Ultimate Fighter 14-ის ფინალისტი, სადაც ნოკაუტით წავაგე ჯონ დოდსონთან.$gq$, $gq$მოვახდინე სენსაცია, როცა გავანადგურე და ნოკაუტში ჩავაგდე მანამდე დაუმარცხებელი ჩემპიონი რენან ბარაო.$gq$, $gq$ჰენრი სეხუდოსთან წაგების შემდეგ ჩავვარდი დოპინგზე (EPO) და მივიღე 2-წლიანი დისკვალიფიკაცია.$gq$, $gq$ვარ სუპერმსუბუქი წონის (Bantamweight) ორგზის ყოფილი ჩემპიონი, ცნობილი ფანტასტიკური ფუტვორქითა და გუნდით "Team Alpha Male".$gq$),
  ($gq$კოდი გარბრანდტი$gq$, $gq$რთული$gq$, $gq$MMA-მდე მქონდა მოკრივის კარიერა, სადაც სამოყვარულო დონეზე 32 მოგება და არცერთი წაგება დავაგროვე.$gq$, $gq$დომინიკ კრუზთან ბრძოლაში ოქტაგონზე ცეკვა და „მაიმუნობა“ დავიწყე, რითაც ფსიქოლოგიურად გავანადგურე.$gq$, $gq$11-0 რეკორდით ჩემპიონობის შემდეგ, ყოფილმა გუნდელმა ტი ჯეი დილაშოუმ ზედიზედ ორჯერ ნოკაუტით დამამარცხა.$gq$, $gq$ჩემი მეტსახელია "No Love", ვარ სუპერმსუბუქი წონის (Bantamweight) ყოფილი ჩემპიონი, ცნობილი სწრაფი ხელებითა და ტატუებით.$gq$),
  ($gq$დომინიკ კრუზი$gq$, $gq$რთული$gq$, $gq$მე ვარ ერთადერთი მებრძოლი, რომელსაც მოგებული აქვს როგორც WEC-ის, ისე UFC-ის სუპერმსუბუქი წონის (Bantamweight) ქამრები მათ გაერთიანებამდე.$gq$, $gq$მძიმე ტრავმების გამო (ქამარი საზარდულის კუნთის გაწყვეტის შემდეგ დავთმე) წლები გამოვტოვე, მაგრამ დავბრუნდი და ტი ჯეი დილაშოუს დამარცხებით ისევ ჩემპიონი გავხდი.$gq$, $gq$ჩემი საფირმო სტილია უნიკალური ფუტვორქი, რის გამოც მოწინააღმდეგეები ჰაერში არტყამდნენ.$gq$, $gq$ჩემი მეტსახელია "The Dominator", ვარ ამერიკელი ლეგენდა და ამჟამად UFC-ის ანალიტიკოსი.$gq$),
  ($gq$ჰენრი სეხუდო$gq$, $gq$საშუალო$gq$, $gq$2008 წლის პეკინის ოლიმპიადაზე თავისუფალ ჭიდაობაში ოქრო მოვიგე და იმ დროისთვის გავხდი ყველაზე ახალგაზრდა ამერიკელი მოჭიდავე, რომელმაც ეს შეძლო.$gq$, $gq$შევწყვიტე დემეტრიუს ჯონსონის 11-მატჩიანი სერია, როცა რევანშში გაყოფილი გადაწყვეტილებით დავამარცხე.$gq$, $gq$მარლონ მორაესის ნოკაუტის შემდეგ, გავხდი ერთდროულად უმსუბუქესი წონისა (Flyweight) და სუპერმსუბუქი წონის (Bantamweight) ჩემპიონი.$gq$, $gq$ჩემი მეტსახელია "Triple C", ვარ ერთადერთი, ვინც ფლობს ოლიმპიურ ოქროს და UFC-ის ორ ქამარს.$gq$),
  ($gq$გლოვერ ტეიშეირა$gq$, $gq$რთული$gq$, $gq$ჩემს პირველ სატიტულო შანსზე 2014 წელს ჯონ ჯონსმა გამანადგურა 5 რაუნდში.$gq$, $gq$42 წლის ასაკში იან ბლაჰოვიჩის დამარცხებით მოვიგე ქვემძიმე წონის (Light Heavyweight) ქამარი.$gq$, $gq$ვარ ბრაზილიელი ქვემძიმე წონის (Light Heavyweight) ყოფილი ჩემპიონი, ყველაზე ხანდაზმული პირველადი ჩემპიონი, ამჟამად ალექს პერეირას მწვრთნელი.$gq$, $gq$$gq$),
  ($gq$იან ბლაჰოვიჩი$gq$, $gq$რთული$gq$, $gq$UFC-ში პირველი 6 ბრძოლიდან 4 წავაგე და გაგდების პირას ვიყავი, შემდეგ კი 8-მატჩიანი სერია გავაკეთე.$gq$, $gq$დომინიკ რეიესის ნოკაუტის შემდეგ მოვიგე ქვემძიმე წონის (Light Heavyweight) ვაკანტური ქამარი, რომელიც ჯონ ჯონსმა დატოვა.$gq$, $gq$ვიყავი პირველი, ვინც ისრაელ ადესანიას პირველი მარცხი აგემა, როცა ის ჩემს წონაში ამოვიდა.$gq$, $gq$ვარ პოლონელი მებრძოლი, ცნობილი ფრაზით "Legendary Polish Power".$gq$),
  ($gq$კაინ ველასკესი$gq$, $gq$საშუალო$gq$, $gq$გავხდი მძიმე წონის (Heavyweight) ჩემპიონი ჩემს მე-9 პროფესიონალურ ბრძოლაში, როცა ბროკ ლესნარი პირველივე რაუნდში ვცემე.$gq$, $gq$ჩემი საფირმო ნიშანი იყო მძიმე წონისთვის (Heavyweight) არარეალური, გაუჩერებელი კარდიო და ტემპი.$gq$, $gq$მაქვს ტრილოგია ჯუნიორ დოს სანტოსთან, სადაც პირველი ბრძოლა ნოკაუტით წავაგე, თუმცა მომდევნო ორი მოვიგე.$gq$, $gq$ვარ მექსიკურ-ამერიკელი მძიმე წონის (Heavyweight) ორგზის ყოფილი ჩემპიონი, მკერდზე ტატუთი "Brown Pride".$gq$),
  ($gq$ჯუნიორ დოს სანტოსი$gq$, $gq$საშუალო$gq$, $gq$UFC-ში სადებიუტო ბრძოლაში აუტსაიდერი ვიყავი, მაგრამ პირველივე რაუნდში, 1 წუთსა და 20 წამზე, ნოკაუტში ჩავაგდე ფაბრისიო ვერდუმი.$gq$, $gq$მოვიგე მძიმე წონის (Heavyweight) ქამარი, როცა პირველ UFC on Fox-ზე 64 წამში დავანოკაუტე კაინ ველასკესი.$gq$, $gq$ჩემი საუკეთესო წლებში ვიყავი საუკეთესო მოკრივე მძიმე წონაში (Heavyweight).$gq$, $gq$ჩემი მეტსახელია "Cigano", ვარ ბრაზილიელი მძიმე წონის (Heavyweight) ყოფილი ჩემპიონი, ცნობილი მომღიმარი ხასიათით.$gq$),
  ($gq$მაიკლ ჩენდლერი$gq$, $gq$საშუალო$gq$, $gq$UFC-მდე ვიყავი Bellator-ის მსუბუქი წონის (Lightweight) სამგზის ჩემპიონი.$gq$, $gq$სადებიუტო UFC ბრძოლაში პირველ რაუნდში ნოკაუტში ჩავაგდე დენ ჰუკერი და ირლანდიურად ვიყვირე კონორისკენ.$gq$, $gq$ტონი ფერგიუსონთან ბრძოლაში პირდაპირი ფრონტ-ქიქით სახეში ის ჰაერში გავთიშე.$gq$, $gq$ჩემი მეტსახელია "Iron", ვარ ამერიკელი ულტრა-ატლეტური მსუბუქი წონის (Lightweight) მებრძოლი.$gq$),
  ($gq$ბენეილ დარიუში$gq$, $gq$რთული$gq$, $gq$დავიბადე ირანში, ასირიულ ქრისტიანულ ოჯახში, საიდანაც მოგვიანებით ამერიკაში გადავსახლდით.$gq$, $gq$მქონდა 8-მატჩიანი სერია მსუბუქ წონაში (მათ შორის ტონი ფერგიუსონის დამარცხება), თუმცა ჩემპიონობის შანსამდე შარლ ოლივეირამ შემატყობინა მარცხი.$gq$, $gq$ჩემი ერთ-ერთი ცნობილი ნოკაუტი იყო დრაკარ კლოუზეს წინააღმდეგ (UFC 248), სადაც მეორე რაუნდში ერთი ზუსტი დარტყმით გავთიშე.$gq$, $gq$ვარ ამერიკელ-ირანელი მსუბუქი წონის (Lightweight) მებრძოლი, ცნობილი გრეპლინგით, თავმდაბლობითა და რელიგიურობით.$gq$),
  ($gq$გილბერტ ბერნსი$gq$, $gq$რთული$gq$, $gq$სატიტულო ბრძოლაში კამარუ უსმანის წინააღმდეგ (ჩემი ყოფილი გუნდელი) პირველ რაუნდში მძიმე ნოკდაუნში ჩავაგდე ის, თუმცა შემდეგ წავაგე.$gq$, $gq$ხამზატ ჩიმაევთან ბრძოლა (UFC 273) გახდა წლის ერთ-ერთი საუკეთესო ომი.$gq$, $gq$ჩემი მეტსახელია "Durinho", ვარ ბრაზილიელი ქვესაშუალო წონის (Welterweight) მებრძოლი, ცნობილი უმაღლესი დონის პარტერითა და მძიმე ხელებით.$gq$, $gq$$gq$),
  ($gq$ხამზატ ჩიმაევი$gq$, $gq$მარტივი$gq$, $gq$UFC-ში დებიუტის დროს, პანდემიის პერიოდში „მებრძოლთა კუნძულზე“, დავამყარე რეკორდი — ორი ბრძოლა 10 დღის ინტერვალით ჩავატარე და ორივე სასტიკად მოვიგე.$gq$, $gq$კევინ ჰოლანდთან და ლი ჯინგლიანთან ისე მოვიგე პირველივე რაუნდში საბმიშენით, რომ მოწინააღმდეგეებს ერთი დარტყმის საშუალებაც არ მივეცი.$gq$, $gq$ნეიტ დიასთან ბრძოლის წინ უმძიმესად ჩავაგდე წონა, რის გამოც მთელი ქარდი აირია და დანა უაიტმა საშუალო წონაში (Middleweight) გადასვლა მითხრა.$gq$, $gq$ჩემი მეტსახელია "Borz" (მგელი), ვარ ჩეჩენი მებრძოლი, რომელიც არაბთა გაერთიანებულ საამიროებს წარმოადგენს და UFC-ის საშუალო წონის (Middleweight) ქამარი მოვიგე.$gq$),
  ($gq$შავკათ რახმონოვი$gq$, $gq$საშუალო$gq$, $gq$მე ვარ პირველი ყაზახი მებრძოლი, რომელმაც UFC-თან კონტრაქტი გააფორმა, და დებიუტში ალექს ოლივეირა „გილიოტინით“ დავაფინიშე.$gq$, $gq$კარიერის პირველი 18 გამარჯვება ფინიშით მოვიპოვე — ნოკაუტით ან საბმიშენით, არცერთი მათგანი ქულებამდე არ მისულა.$gq$, $gq$ჯეფ ნილთან ბრძოლაში ფეხზე მდგომ მოწინააღმდეგეს მოგუდვა გავუკეთე და გავთიშე.$gq$, $gq$ჩემი მეტსახელია "Nomad", ვარ ყაზახეთის უდიდესი MMA ვარსკვლავი ქვესაშუალო წონაში (Welterweight), ვატარებ ტრადიციულ ყაზახურ ქუდს.$gq$),
  ($gq$დიეგო ლოპესი$gq$, $gq$რთული$gq$, $gq$წლების განმავლობაში ვმუშაობდი მწვრთნელად (მათ შორის ვეხმარებოდი ალექსა გრასოს), სანამ შანსი მივიღე UFC-ში მოკლე დროში მოვსულიყავი მოვსარ ევლოევის წინააღმდეგ, სადაც წავაგე, მაგრამ ხალხის გული მოვიგე.$gq$, $gq$პირველი წაგების შემდეგ გავაკეთე სერია ქვემსუბუქ წონაში (Featherweight), სადაც ფინიშებით დავამარცხე გევინ ტუკერი და სოდიქ იუსუფი.$gq$, $gq$გამოვირჩევი სპორტში ერთ-ერთი ყველაზე სახიფათო ბრაზილიური ჯიუ-ჯიცუთი.$gq$, $gq$ვარ ბრაზილიელი, რომელიც მექსიკაში ცხოვრობს, მაქვს ცნობილი გრძელი ვარცხნილობა და ვარ ქვემსუბუქი დივიზიონის ერთ-ერთი ყველაზე პოპულარული მებრძოლი.$gq$),
  ($gq$როის გრეისი$gq$, $gq$რთული$gq$, $gq$ტურნირებზე ჩემი წონა 80 კილოგრამამდე იყო, მაგრამ აბსოლუტურ კატეგორიაში ჩემზე ბევრად მძიმე მოწინააღმდეგეებს ვამარცხებდი.$gq$, $gq$ვმონაწილეობდი UFC-ის ისტორიაში ყველაზე ხანგრძლივ ბრძოლაში კენ შემროკის წინააღმდეგ (UFC 5), რომელიც 36 წუთი გაგრძელდა და ფრედ დასრულდა.$gq$, $gq$გავხდი UFC 1, UFC 2 და UFC 4 ტურნირების გამარჯვებული, ყველა ბრძოლა საბმიშენით მოვიგე.$gq$, $gq$ვარ ბრაზილიელი ლეგენდა, რომელიც ოქტაგონზე ტრადიციული ჯიუ-ჯიცუს კიმონოთი გამოდიოდა, და ჩემი ოჯახი UFC-ის დამფუძნებელია.$gq$),
  ($gq$ჩაკ ლიდელი$gq$, $gq$საშუალო$gq$, $gq$ჩემპიონობამდე ორგანიზაციამ იაპონიაში გამიშვა Pride-ის გრან-პრიზე, სადაც კუინტონ „რემპეიჯ“ ჯექსონთან ტექნიკური ნოკაუტით წავაგე.$gq$, $gq$ჩემი ყველაზე სისხლიანი დაპირისპირება იყო ტიტო ორტისთან, რომელიც ორჯერვე ნოკაუტით დავამარცხე.$gq$, $gq$ვფლობდი ქვემძიმე წონის (Light Heavyweight) ქამარს, ჩემი საფირმო იყო წარმოუდგენელი თეიქდაუნ-დაცვა და მარჯვენა ოვერჰენდი.$gq$, $gq$ჩემი მეტსახელია "The Iceman", ვარ UFC-ის ოქროს ხანის მთავარი სახე, ცნობილი იროკეზის ვარცხნილობითა და თავზე ტატუთი.$gq$),
  ($gq$რენდი კუტიური$gq$, $gq$რთული$gq$, $gq$რამდენჯერმე წავედი სპორტიდან და დავბრუნდი; 43 წლის ასაკში ტიმ სილვია 5 რაუნდში დავამარცხე და ისევ ჩემპიონი გავხდი.$gq$, $gq$გავხდი პირველი მებრძოლი ისტორიაში, რომელმაც ქამარი ორ წონაში (მძიმე და ქვემძიმე) მოიპოვა.$gq$, $gq$ჩემი მეტსახელია "The Natural", ვარ ამერიკელი ჭიდაობის ლეგენდა და დიდების დარბაზის წევრი.$gq$, $gq$$gq$),
  ($gq$ტიტო ორტისი$gq$, $gq$რთული$gq$, $gq$ვფლობდი ქვემძიმე წონის (Light Heavyweight) ქამარს, ერთ-ერთი ცნობილი ბრძოლა იყო იუკი კონდოს წინააღმდეგ (UFC 29), რომელიც 2 წუთში კისერზე მტკივნეული ილეთით დავაფინიშე.$gq$, $gq$მქონდა უდიდესი კონფლიქტი დანა უაითთან — 2007 წელს ჩვენს შორის კრივის ბრძოლაც კი ჩაინიშნა, მაგრამ ჩაიშალა: დანა ამბობს, რომ აწონვაზე არ გამოვცხადდი, მე კი ვამტკიცებ, რომ მიზეზი შეთანხმებული 50/50 კონტრაქტის დარღვევა იყო.$gq$, $gq$ჩემი საფირმო რიტუალი იყო მოგების შემდეგ მოწინააღმდეგის „საფლავის გათხრის“ იმიტაცია.$gq$, $gq$ჩემი მეტსახელია "The Huntington Beach Bad Boy", ვარ ქვემძიმე წონის (Light Heavyweight) ყოფილი ჩემპიონი, ცნობილი ქერად შეღებილი თმითა და თრეშთოქით.$gq$),
  ($gq$ბი ჯეი პენი$gq$, $gq$რთული$gq$, $gq$გავხდი პირველი არა-ბრაზილიელი მებრძოლი, რომელმაც ჯიუ-ჯიცუს მსოფლიო ჩემპიონატზე შავი ქამრების კატეგორიაში ოქრო მოიპოვა.$gq$, $gq$მაქვს ორი ბრძოლა ჟორჟ სენ-პიერთან; პირველში ახლოს ვიყავი მოგებასთან, რევანშში კი ჩემმა კუთხემ მე-4 რაუნდის შემდეგ შეაჩერა ბრძოლა.$gq$, $gq$რენდი კუტიურის შემდეგ, გავხდი მეორე მებრძოლი, რომელმაც ქამარი ორ წონაში — ქვესაშუალოსა (Welterweight) და მსუბუქში (Lightweight) — მოიგო.$gq$, $gq$ჩემი მეტსახელია "The Prodigy", ვარ ჰავაიელი ლეგენდა, ითვლება მსუბუქი წონის (Lightweight) ისტორიაში ერთ-ერთ ყველაზე ნიჭიერ მებრძოლად.$gq$),
  ($gq$ვიტორ ბელფორტი$gq$, $gq$რთული$gq$, $gq$UFC-ში დებიუტი 19 წლის ასაკში შედგა (UFC 12), სადაც ერთ საღამოს ორივე მოწინააღმდეგე ტექნიკური ნოკაუტით დავამარცხე.$gq$, $gq$კარიერის გვიან პერიოდში ზედიზედ სამი მეტოქე დავაფინიშე: მაიკლ ბისპინგი ჰედ-ქიქით, ლუკ როკჰოლდი კი მბრუნავი ფეხის დარტყმით გავთიშე.$gq$, $gq$მოვიგე ქვემძიმე წონის (Light Heavyweight) ქამარი რენდი კუტიურთან, როცა ჩემმა დარტყმამ მას თვალი დაუზიანა.$gq$, $gq$ჩემი მეტსახელია "The Phenom", ვარ ბრაზილიელი ნოკაუტერი, ცნობილი სწრაფი ხელებით.$gq$),
  ($gq$დენ ჰენდერსონი$gq$, $gq$რთული$gq$, $gq$ვიყავი Pride-ის ერთადერთი მებრძოლი, რომელიც ერთდროულად ორ წონაში ფლობდა ქამარს.$gq$, $gq$ჩემი ყველაზე ცნობილი მომენტია UFC 100-ზე მაიკლ ბისპინგის ნოკაუტი, სადაც დაცემულ მეტოქეს ზემოდან დავახტი.$gq$, $gq$ჩემი იარაღი იყო ჭიდაობის ბაზისი და მარჯვენა ხელი, რომელსაც "H-Bomb" შეარქვეს.$gq$, $gq$ჩემი მეტსახელია "Hendo", ვარ ამერიკელი ვეტერანი, რომელიც 46 წლის ასაკშიც იბრძოდა ჩემპიონობისთვის.$gq$),
  ($gq$მაიკლ ბისპინგი$gq$, $gq$რთული$gq$, $gq$ვიტორ ბელფორტთან მიღებული დარტყმის გამო ბადურა ამეცალა და პრაქტიკულად დავბრმავდი, კარიერის ბოლო ნაწილი ცალი თვალით ვიჩხუბე.$gq$, $gq$მოვიგე რეალითი შოუ The Ultimate Fighter 3 და წლების განმავლობაში ვიყავი UFC-ის მთავარი ვარსკვლავი ევროპაში.$gq$, $gq$მოვახდინე სენსაცია, როცა მოკლე დროში ჩავანაცვლე მებრძოლი და ნოკაუტით დავამარცხე ლუკ როკჰოლდი.$gq$, $gq$ჩემი მეტსახელია "The Count", ვარ პირველი ბრიტანელი ჩემპიონი, ამჟამად UFC-ის კომენტატორი.$gq$),
  ($gq$კენ შემროკი$gq$, $gq$რთული$gq$, $gq$UFC 1-მდე პოპულარობა მოვიპოვე იაპონურ ორგანიზაცია Pancrase-ში.$gq$, $gq$მქონდა ლეგენდარული დაპირისპირება როის გრეისთან და გავხდი UFC-ის პირველი "Superfight" ჩემპიონი.$gq$, $gq$UFC-ის პარალელურად ვიყავი WWF/WWE-ის რესლინგის დიდი ვარსკვლავი.$gq$, $gq$ჩემი მეტსახელია "The World's Most Dangerous Man", ვარ UFC-ის ყველაზე პირველი ტურნირების მონაწილე და დიდების დარბაზის თავდაპირველი წევრი.$gq$),
  ($gq$მარკ კოულმენი$gq$, $gq$რთული$gq$, $gq$1992 წლის ბარსელონას ოლიმპიადაზე თავისუფალ ჭიდაობაში მე-7 ადგილი დავიკავე.$gq$, $gq$მოვიგე UFC 10 და UFC 11 ტურნირები ზედიზედ.$gq$, $gq$UFC 12-ზე დავამარცხე დენ სევერნი და გავხდი პირველი ოფიციალური UFC-ის მძიმე წონის (Heavyweight) ჩემპიონი.$gq$, $gq$მივიჩნევი "The Godfather of Ground and Pound"-ად, რადგან პირველმა დავნერგე ტაქტიკა: დაგდება და ზემოდან გრაუნდ-ენდ-ფაუნდი.$gq$)
) as v(answer, level, clue1, clue2, clue3, clue4)
where not exists (
  select 1 from public.guess_who_questions e
  where e.answer = v.answer and e.level = v.level and e.is_active = true
);

end;
$ufc_seed$ language plpgsql;

commit;

-- 2d. Post-write check — run after 2a-2c to confirm the new state.
select 'quiz_questions AFTER' as what, level, is_active, count(*) as n
from public.quiz_questions
group by level, is_active
order by 1, 2, 3;

select 'guess_who_questions AFTER' as what, level, is_active, count(*) as n
from public.guess_who_questions
group by level, is_active
order by 1, 2, 3;
